"use client";

import * as React from "react";

export interface FlipGroupOptions {
  /** Children to animate, matched inside the container. */
  selector?: string;
  /** Milliseconds. Defaults to the `--godui-duration-base` token (260ms). */
  duration?: number;
  /**
   * Any CSS easing, incl. linear() springs. Defaults to the container's own
   * `transition-timing-function` (give it an `ease-spring-*` class), else an
   * ease-out-expo curve.
   */
  easing?: string;
  /**
   * The element whose position is tracked for a candidate (default: the
   * candidate itself). The offset still animates the candidate, so a box can
   * glide by the distance its content moved, e.g. a button whose padding
   * snapped: moving the box keeps its icon from being clipped by it.
   */
  measure?: (el: HTMLElement) => Element;
}

const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect;

type Point = { x: number; y: number };

/** The element's own `translate` as [x, y] CSS lengths ("0px" when unset). */
function ownTranslate(el: HTMLElement): [string, string] {
  const value =
    el.ownerDocument.defaultView?.getComputedStyle(el).translate ||
    el.style.translate ||
    "none";
  if (value === "none") return ["0px", "0px"];
  const [x = "0px", y = "0px"] = value.trim().split(/\s+/);
  return [x, y];
}

/** `length + offset px`, folded to a plain px value when possible. */
function plus(length: string, offset: number): string {
  const px = /^(-?[\d.]+)px$/.exec(length);
  if (px) return `${Number(px[1]) + offset}px`;
  return `calc(${length} + ${offset}px)`;
}

/** One translate length (`8px`, `-100%`, `calc(-100% + 8px)`) in px. */
function lengthPx(length: string, size: number): number | null {
  const inner = /^calc\((.*)\)$/.exec(length.trim())?.[1] ?? length;
  let total = 0;
  for (const term of inner.replace(/\s-\s/g, " + -").split(/\s\+\s/)) {
    const match = /^(-?[\d.]+(?:e-?\d+)?)(px|%)$/.exec(term.trim());
    if (!match) return null;
    const n = Number(match[1]);
    total += match[2] === "%" ? (n * size) / 100 : n;
  }
  return total;
}

/** A translate value (`"8px 0px"`, `"-100%"`) as px for `el`, or null. */
function translatePx(value: string, el: HTMLElement): Point | null {
  if (!value || value === "none") return { x: 0, y: 0 };
  const parts = value.trim().match(/(?:calc\([^)]*\)|[^\s]+)/g) ?? [];
  const x = lengthPx(parts[0] ?? "0px", el.offsetWidth);
  const y = lengthPx(parts[1] ?? "0px", el.offsetHeight);
  return x === null || y === null ? null : { x, y };
}

/** A CSS time (`260ms`, `0.3s`) in milliseconds; 260 when unset or invalid. */
function toMs(value: string | undefined): number {
  const n = Number.parseFloat(value ?? "");
  if (!Number.isFinite(n)) return 260;
  return /\ds\s*$/.test(value ?? "") ? n * 1000 : n;
}

/**
 * Running FLIPs by element, shared by every group: an element moved by one
 * group (e.g. a Collapsible) can be a candidate of another (its sibling
 * Collapsible). Any group cancels and carries it; nobody baselines it mid-flight.
 */
const RUNNING = new WeakMap<Element, Animation>();

const self = (el: HTMLElement): Element => el;

/**
 * Finite animations moving `el` that aren't a FLIP of this hook's (e.g. a
 * Collapsible panel's clip-edge sweep moving its box and children): a
 * baseline taken mid-way would include their offsets.
 */
function foreignMoves(el: Element): Animation[] {
  if (typeof el.getAnimations !== "function") return [];
  return el.getAnimations().filter((animation) => {
    if (animation === RUNNING.get(el) || animation.playState !== "running") {
      return false;
    }
    const effect = animation.effect as Partial<KeyframeEffect> | null;
    const end = Number(effect?.getComputedTiming?.().endTime);
    if (!Number.isFinite(end)) return false;
    const frames =
      typeof effect?.getKeyframes === "function" ? effect.getKeyframes() : [];
    return frames.some((f) => "translate" in f || "transform" in f);
  });
}

/** Each matched child's position relative to the container. */
function measure(
  container: HTMLElement,
  selector: string,
  track: (el: HTMLElement) => Element,
) {
  const origin = container.getBoundingClientRect();
  const positions = new Map<Element, Point>();
  for (const el of container.querySelectorAll<HTMLElement>(selector)) {
    const rect = track(el).getBoundingClientRect();
    positions.set(el, { x: rect.left - origin.left, y: rect.top - origin.top });
  }
  return positions;
}

/**
 * FLIP for layout changes without animating layout: when `trigger` changes,
 * children (default `[data-flip]`) whose position moved play an inverse offset
 * back to rest via WAAPI on the individual `translate` property, added to the
 * element's own translate. Replace-composited `translate` runs on the
 * compositor (Chrome won't composite `composite: "add"`) and sits outside the
 * element's `scale`/`rotate`, so scaled children don't distort the distance.
 * Sizes snap; only translate animates.
 *
 * Positions are relative to the container (scrolling between triggers is
 * ignored). If a previous FLIP is still running, its current visual offset is
 * read before cancelling it and carried into the new animation, so an
 * interruption starts from where the element is drawn instead of jumping.
 * Layout changes that no trigger accounts for (content loading, reflow) are
 * picked up by a ResizeObserver and become the new baseline without
 * animating — once no FLIP (from this group or another) and no other finite
 * translate animation (a reveal's sweep) is running on the container or the
 * candidates, so a baseline never includes an in-flight offset.
 */
export function useFlipGroup(
  containerRef: React.RefObject<HTMLElement | null>,
  trigger: unknown,
  {
    selector = "[data-flip]",
    duration,
    easing,
    measure: track = self,
  }: FlipGroupOptions = {},
): void {
  const last = React.useRef(new Map<Element, Point>());
  const dirty = React.useRef(false);
  const resizes = React.useRef<ResizeObserver | null>(null);
  const settle = React.useRef<() => void>(() => {});
  // Read through a ref: an inline `measure` needn't re-run the effects.
  const tracker = React.useRef(track);
  tracker.current = track;

  // Re-baseline on resizes no trigger caused, once nothing is mid-FLIP.
  React.useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof ResizeObserver === "undefined") return;
    settle.current = () => {
      const busy: Array<[Element, Animation]> = [];
      const candidates = [...container.querySelectorAll(selector)];
      for (const el of candidates) {
        const animation = RUNNING.get(el);
        if (animation) busy.push([el, animation]);
      }
      const foreign = [container, ...candidates].flatMap(foreignMoves);
      if (busy.length === 0 && foreign.length === 0) {
        dirty.current = false;
        last.current = measure(container, selector, tracker.current);
        return;
      }
      dirty.current = true;
      for (const [el, animation] of busy) {
        // `finished` can settle before `onfinish` runs; clear the entry here
        // too, or settle() would keep re-waiting on a resolved promise.
        const done = () => {
          if (RUNNING.get(el) === animation) RUNNING.delete(el);
          settle.current();
        };
        animation.finished?.then(done, done);
      }
      const again = () => settle.current();
      for (const animation of foreign) animation.finished?.then(again, again);
    };
    const observer = new ResizeObserver(() => settle.current());
    resizes.current = observer;
    observer.observe(container);
    for (const el of container.querySelectorAll(selector)) observer.observe(el);
    return () => {
      observer.disconnect();
      resizes.current = null;
    };
  }, [containerRef, selector]);

  // `trigger` is in the deps purely as the signal to re-measure.
  useIsoLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const view = container.ownerDocument.defaultView;
    const origin = container.getBoundingClientRect();
    const reduce =
      view?.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    const containerEase =
      view?.getComputedStyle(container).transitionTimingFunction;
    const ease =
      easing ??
      (containerEase && containerEase !== "ease"
        ? containerEase
        : "cubic-bezier(0.16, 1, 0.3, 1)");
    const ms =
      duration ??
      toMs(
        view
          ?.getComputedStyle(container)
          .getPropertyValue("--godui-duration-base"),
      );
    const next = new Map<Element, Point>();
    for (const el of container.querySelectorAll<HTMLElement>(selector)) {
      resizes.current?.observe(el);
      const tracked = tracker.current(el);
      let rect = tracked.getBoundingClientRect();
      let carry: Point = { x: 0, y: 0 };
      const active = RUNNING.get(el);
      if (active) {
        // The rest it was gliding to: if the element's own translate changed
        // since (a class moved it), the running FLIP still holds the old one.
        // Duck-typed: `instanceof` fails across realms (an iframe whose DOM
        // is driven from the parent window's JS).
        const effect = active.effect as Partial<KeyframeEffect> | null;
        const frames =
          typeof effect?.getKeyframes === "function"
            ? effect.getKeyframes()
            : [];
        const target = frames[frames.length - 1]?.translate;
        active.cancel();
        RUNNING.delete(el);
        const settled = tracked.getBoundingClientRect();
        carry = { x: rect.left - settled.left, y: rect.top - settled.top };
        rect = settled;
        const before =
          typeof target === "string" ? translatePx(target, el) : null;
        const after = translatePx(ownTranslate(el).join(" "), el);
        if (before && after) {
          carry.x += after.x - before.x;
          carry.y += after.y - before.y;
        }
      }
      const now = { x: rect.left - origin.left, y: rect.top - origin.top };
      next.set(el, now);
      const prev = last.current.get(el);
      if (!prev || reduce || typeof el.animate !== "function") continue;
      const dx = prev.x - now.x + carry.x;
      const dy = prev.y - now.y + carry.y;
      if (dx === 0 && dy === 0) continue;
      const [ownX, ownY] = ownTranslate(el);
      const animation = el.animate(
        [
          { translate: `${plus(ownX, dx)} ${plus(ownY, dy)}` },
          { translate: `${ownX} ${ownY}` },
        ],
        { duration: ms, easing: ease },
      );
      RUNNING.set(el, animation);
      animation.onfinish = () => {
        if (RUNNING.get(el) === animation) RUNNING.delete(el);
        if (dirty.current) settle.current();
      };
    }
    last.current = next;
  }, [trigger, selector, duration, easing]);
}

"use client";

import * as React from "react";

export type IndicatorBox = { x: number; y: number; w: number; h: number };

export interface ActiveIndicatorOptions {
  /** Matches the active element inside the container, e.g. '[role="tab"][data-state="active"]'. */
  active: string;
  /** Matches every candidate; each is observed for resizes, e.g. '[role="tab"]'. */
  items: string;
  /** Attributes whose change can move the active element. Default ["data-state"]. */
  attributes?: string[];
  /** Map the active element to the indicator's box. Default: its offset box. */
  box?: (el: HTMLElement, container: HTMLElement) => IndicatorBox;
  /** false → the indicator is hidden and `data-indicator` removed. Default true. */
  enabled?: boolean;
}

const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect;

const offsetBox = (el: HTMLElement): IndicatorBox => ({
  x: el.offsetLeft,
  y: el.offsetTop,
  w: el.offsetWidth,
  h: el.offsetHeight,
});

/** A CSS time (`260ms`, `0.3s`) in milliseconds; 260 when unset or invalid. */
function toMs(value: string | undefined): number {
  const n = Number.parseFloat(value ?? "");
  if (!Number.isFinite(n)) return 260;
  return /\ds\s*$/.test(value ?? "") ? n * 1000 : n;
}

/**
 * One indicator that follows the active element inside a container (tabs,
 * a single-select toggle group, a command list's selection). Its box snaps —
 * width, height and translate are set directly — and when the active element
 * changes by attribute, a FLIP plays `translate` + `scale` from the previous
 * box on the compositor. Item inserts/removals and resizes snap instead. A
 * slide in flight is cancelled and the next starts from where it is drawn; a
 * resize during a slide is applied when it finishes. The container gets
 * `data-indicator="ready"` once the indicator is placed, so components can
 * keep their own active styling until then (server render, first paint).
 *
 * The indicator's easing is read from its computed `transition-timing-function`
 * (give it an `ease-spring-*` class); duration from `--godui-duration-base`.
 */
export function useActiveIndicator(
  containerRef: React.RefObject<HTMLElement | null>,
  indicatorRef: React.RefObject<HTMLElement | null>,
  options: ActiveIndicatorOptions,
): void {
  const { active, items, enabled = true } = options;
  const attributes = (options.attributes ?? ["data-state"]).join(",");
  // `box` is usually an inline function; read the latest without re-subscribing.
  const boxRef = React.useRef(options.box);
  boxRef.current = options.box;

  useIsoLayoutEffect(() => {
    const container = containerRef.current;
    const indicator = indicatorRef.current;
    if (!container) return;
    if (!enabled || !indicator) {
      container.removeAttribute("data-indicator");
      return;
    }
    const view = container.ownerDocument.defaultView;
    let shown: IndicatorBox | null = null;
    let running: Animation | null = null;
    let dirty = false;

    const place = (animate: boolean) => {
      const el = container.querySelector<HTMLElement>(active);
      if (!el) {
        container.removeAttribute("data-indicator");
        shown = null;
        return;
      }
      const box = (boxRef.current ?? offsetBox)(el, container);
      let from = shown;
      if (running) {
        const drawn = indicator.getBoundingClientRect();
        const origin = container.getBoundingClientRect();
        if (drawn.width > 0 && drawn.height > 0) {
          // offset* (the target) is scroll-independent; the drawn rect isn't.
          from = {
            x:
              drawn.left -
              origin.left -
              container.clientLeft +
              container.scrollLeft,
            y:
              drawn.top -
              origin.top -
              container.clientTop +
              container.scrollTop,
            w: drawn.width,
            h: drawn.height,
          };
        }
        running.cancel();
        running = null;
      }
      indicator.style.width = `${box.w}px`;
      indicator.style.height = `${box.h}px`;
      indicator.style.translate = `${box.x}px ${box.y}px`;
      container.setAttribute("data-indicator", "ready");
      shown = box;

      const moved =
        from != null &&
        (from.x !== box.x ||
          from.y !== box.y ||
          from.w !== box.w ||
          from.h !== box.h);
      if (!animate || !from || !moved || box.w === 0 || box.h === 0) return;
      if (typeof indicator.animate !== "function") return;
      if (view?.matchMedia?.("(prefers-reduced-motion: reduce)").matches)
        return;
      const style = view?.getComputedStyle(indicator);
      const duration = toMs(style?.getPropertyValue("--godui-duration-base"));
      const easing = style?.transitionTimingFunction || "ease-out";
      const animation = indicator.animate(
        [
          {
            translate: `${from.x}px ${from.y}px`,
            scale: `${from.w / box.w} ${from.h / box.h}`,
          },
          { translate: `${box.x}px ${box.y}px`, scale: "1 1" },
        ],
        { duration, easing },
      );
      running = animation;
      animation.onfinish = () => {
        if (running !== animation) return;
        running = null;
        if (dirty) {
          dirty = false;
          place(false);
        }
      };
    };

    const resizes =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(() => {
            if (running) dirty = true;
            else place(false);
          });
    // The container and every item: an item can change size (label, font
    // load, flex-1 in a resized container) while the container's box doesn't.
    const observeItems = () => {
      if (!resizes) return;
      resizes.disconnect();
      resizes.observe(container);
      for (const item of container.querySelectorAll(items)) {
        resizes.observe(item);
      }
    };

    place(false);
    observeItems();
    const mutations = new MutationObserver((records) => {
      // Selection moved → slide. Items added/removed (filtering) → snap.
      if (records.some((record) => record.type === "childList")) {
        observeItems();
        place(false);
      } else {
        place(true);
      }
    });
    mutations.observe(container, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: attributes.split(","),
    });
    return () => {
      mutations.disconnect();
      resizes?.disconnect();
      running?.cancel();
    };
  }, [containerRef, indicatorRef, active, items, attributes, enabled]);
}

"use client";

import * as React from "react";

/**
 * The mount rule for selection pops: `true` once `value` has changed since
 * this component mounted — never on first paint or remount (menu items mount
 * on every open). Compared during render, so it flips in the same commit as
 * the change. Set it as `data-animate` and gate the pop keyframe on it.
 *
 * If the animated element is Presence-managed (a Radix `*Indicator`), also
 * gate the keyframe on the element's own "on" state
 * (`data-[state=checked]:`): otherwise the commit that unchecks it adds the
 * keyframe, Presence sees a new animation, and the indicator re-pops before
 * it disappears.
 */
export function useAnimateOnChange(value: unknown): boolean {
  const [animate, setAnimate] = React.useState(false);
  const [last, setLast] = React.useState(value);
  if (!Object.is(value, last)) {
    setLast(value);
    setAnimate(true);
  }
  return animate;
}

import * as React from "react";

/**
 * One callback ref that points both `local` and the caller's `ref` (callback
 * or object) at the same node. React 19: a callback ref may return its own
 * cleanup, which React then calls instead of `ref(null)`; it's passed through,
 * so a caller's cleanup runs on unmount and their ref is never called with null.
 */
export function useMergedRef<T>(
  local: React.RefObject<T | null>,
  ref: React.Ref<T> | undefined,
) {
  return React.useCallback(
    (node: T | null) => {
      local.current = node;
      if (typeof ref === "function") {
        const cleanup = ref(node);
        return () => {
          local.current = null;
          if (typeof cleanup === "function") cleanup();
          else ref(null);
        };
      }
      if (ref) ref.current = node;
      return () => {
        local.current = null;
        if (ref) ref.current = null;
      };
    },
    [local, ref],
  );
}

"use client";

// The engine behind GodUI's faked height animations (Accordion, Collapsible).
// A panel's height snaps; its box (clipped) slides from under what's above it
// while the box's content slides the other way by the same amount, so the
// content holds still and only the clip edge sweeps. Whatever comes after the
// panel FLIPs on the same clock (duration + curve), so it rides the edge. A
// closing panel leaves the flow at once and sweeps back up while the content
// below rises. Every piece starts from where it's drawn, so reversing mid-way
// never jumps. GPU-only: `translate` and `opacity`.

import * as React from "react";
import { flushSync } from "react-dom";

const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect;

/** Reveal roots: each one watches every open-state change beneath it. */
const ROOTS = '[data-slot="accordion"], [data-slot="collapsible"]';
/** Elements whose `data-state` marks a panel opening or closing. */
const TOGGLES = new Set(["accordion-item", "collapsible"]);

/** One clock for every piece of a change. */
export interface RevealTiming {
  ms: number;
  /** The spring shared by the clip edges, the FLIPs and the glides. */
  ease: string;
  /** The fades' curve (`--ease-out-expo`). */
  fade: string;
  /** Delay between the content blocks fading in. */
  stagger: number;
  reduce: boolean;
}

/** A CSS time (`260ms`, `0.3s`) in milliseconds; `fallback` when unset. */
function toMs(value: string | undefined, fallback: number): number {
  const n = Number.parseFloat(value ?? "");
  if (!Number.isFinite(n)) return fallback;
  return /\ds\s*$/.test(value ?? "") ? n * 1000 : n;
}

/** `length + offset px`, folded to a plain px value when possible. */
function plus(length: string, offset: number): string {
  const px = /^(-?[\d.]+)px$/.exec(length);
  if (px) return `${Number(px[1]) + offset}px`;
  return `calc(${length} + ${offset}px)`;
}

/** The element's own `translate` as [x, y] lengths, or null when unset. */
function ownTranslate(el: Element): [string, string] | null {
  const value = el.ownerDocument.defaultView?.getComputedStyle(el).translate;
  if (!value || value === "none") return null;
  const [x = "0px", y = "0px"] = value.trim().split(/\s+/);
  return [x, y];
}

/** The element's current vertical `translate` in px (0 when unset). */
function drawnY(el: Element): number {
  const own = ownTranslate(el);
  return (own && Number.parseFloat(own[1])) || 0;
}

/** The element's opacity (1 when unknown). */
function opacityOf(el: Element): number {
  const value = el.ownerDocument.defaultView?.getComputedStyle(el).opacity;
  const n = Number.parseFloat(value ?? "");
  return Number.isFinite(n) ? n : 1;
}

/** The element's `filter: opacity()` level (1 when it has none). */
function filterOpacityOf(el: Element): number {
  const value = el.ownerDocument.defaultView?.getComputedStyle(el).filter;
  const n = Number.parseFloat(
    /opacity\(([^)]*)\)/.exec(value ?? "")?.[1] ?? "",
  );
  return Number.isFinite(n) ? n : 1;
}

/**
 * The clock for a change, read off a reveal root: opening takes
 * `--godui-duration-base`, a pure collapse the quicker `--godui-duration-fast`.
 * The spring is the root's `transition-timing-function` (its `ease-spring-*`
 * class), else ease-out-expo.
 */
export function revealTiming(
  root: HTMLElement,
  opening: boolean,
): RevealTiming {
  const view = root.ownerDocument.defaultView;
  const style = view?.getComputedStyle(root);
  const fast = toMs(style?.getPropertyValue("--godui-duration-fast"), 150);
  const ms = opening
    ? toMs(style?.getPropertyValue("--godui-duration-base"), 260)
    : fast;
  const ease = style?.transitionTimingFunction;
  const expo =
    style?.getPropertyValue("--ease-out-expo").trim() ||
    "cubic-bezier(0.16, 1, 0.3, 1)";
  return {
    ms,
    ease: ease && ease !== "ease" ? ease : expo,
    fade: expo,
    stagger: fast / 4,
    reduce:
      typeof view?.matchMedia === "function" &&
      view.matchMedia("(prefers-reduced-motion: reduce)").matches,
  };
}

/** Running sweeps (edge, counter-moves, fades) by panel box. */
const SWEEPS = new WeakMap<Element, Animation[]>();

export interface Sweep {
  /** Slides `-distance → 0` (opening) or back; clipped while it does. */
  box: HTMLElement;
  /** Slide the other way, so they hold still. None: the box doesn't move. */
  layers: HTMLElement[];
  /** Fade in (a beat apart on a fresh open) or out. */
  blocks: HTMLElement[];
  open: boolean;
  /** How far the edge travels: the room the panel takes in the layout. */
  distance: number;
}

/**
 * Sweep a panel's clip edge: the box moves `from → to` and its layers the
 * opposite way, so they hold still on screen while the edge travels. Opening,
 * the blocks fade in a beat apart; closing, they fade out ahead of the edge.
 * Mid-sweep, it carries on from what's drawn. Reduced motion: fades only.
 * While the box moves it has `data-sweeping` (clip it, let the pointer through
 * it): mid-sweep it overlaps whatever sits above the panel.
 */
export function sweepPanel(
  { box, layers, blocks, open, distance }: Sweep,
  t: RevealTiming,
) {
  if (typeof box.animate !== "function") return;
  const previous = SWEEPS.get(box) ?? [];
  // Read what's drawn before cancelling, so a reversal carries on from there.
  // A finished close (held by its fill) starts fresh.
  const running = previous.some((a) => a.playState !== "finished");
  const drawn = running ? drawnY(box) : null;
  // The box itself fades with `filter: opacity()`: its `opacity` belongs to
  // the hold keyframe, and Chrome won't composite two opacity animations on
  // one element.
  const level = (block: Element) =>
    block === box ? filterOpacityOf(block) : opacityOf(block);
  const shown = blocks.map((block) => (running ? level(block) : null));
  for (const animation of previous) animation.cancel();
  const fill: FillMode = open ? "backwards" : "forwards";
  const animations: Animation[] = blocks.map((block, i) => {
    const rest = level(block);
    const from = shown[i] ?? (open ? 0 : rest);
    const to = open ? rest : 0;
    // Fresh opens cascade (capped at 4 beats); reversals and exits move as
    // one. Every fade still ends with the edge: one clock, one last frame.
    // Clamped to the clock: a 0ms token must not make a negative duration
    // (animate() would throw inside the observer).
    const delay =
      open && !running ? Math.min(Math.min(i, 3) * t.stagger, t.ms) : 0;
    const frames =
      block === box
        ? [{ filter: `opacity(${from})` }, { filter: `opacity(${to})` }]
        : [{ opacity: from }, { opacity: to }];
    return block.animate(frames, {
      duration: Math.max(0, t.ms - delay),
      delay,
      easing: t.fade,
      fill,
    });
  });
  const own = ownTranslate(box);
  const ownY = own ? Number.parseFloat(own[1]) || 0 : 0;
  const from = drawn === null ? (open ? -distance : 0) : drawn - ownY;
  const to = open ? 0 : -distance;
  if (!t.reduce && from !== to && layers.length > 0) {
    box.setAttribute("data-sweeping", "");
    const timing = { duration: t.ms, easing: t.ease, fill };
    const at = (el: Element, y: number) => {
      const base = el === box ? own : ownTranslate(el);
      return base ? `${base[0]} ${plus(base[1], y)}` : `0 ${y}px`;
    };
    animations.push(
      box.animate(
        [{ translate: at(box, from) }, { translate: at(box, to) }],
        timing,
      ),
      ...layers.map((layer) =>
        layer.animate(
          [{ translate: at(layer, -from) }, { translate: at(layer, -to) }],
          timing,
        ),
      ),
    );
  }
  SWEEPS.set(box, animations);
  // A closed panel stays drawn as it ended (held by the forwards fills) until
  // it's hidden or reopened; an open lets go once it's done.
  if (open) {
    Promise.all(animations.map((a) => a.finished)).then(
      () => {
        if (SWEEPS.get(box) !== animations) return;
        SWEEPS.delete(box);
        box.removeAttribute("data-sweeping");
      },
      () => {},
    );
  }
}

/** Closing Collapsible panels out of the flow: the room each one took. */
const LEFT = new WeakMap<
  HTMLElement,
  { room: number; style: [string, string, string, string] }
>();
const PLACED = ["position", "top", "left", "width"] as const;

/** A Collapsible's own content (not a nested Collapsible's). */
export function contentOf(root: Element): HTMLElement | null {
  for (const el of root.querySelectorAll<HTMLElement>(
    '[data-slot="collapsible-content"]',
  )) {
    if (el.closest('[data-slot="collapsible"]') === root) return el;
  }
  return null;
}

/**
 * Take a closing panel out of the flow right where it's drawn (absolute, at
 * its measured offset and width), so what follows rises at once. Returns the
 * room it took in `root`. Idempotent: every reveal root above it sees the
 * same change, and whichever handles it first must measure the flow.
 */
export function leaveFlow(box: HTMLElement, root: HTMLElement): number {
  const known = LEFT.get(box);
  if (known) return known.room;
  if (box.hidden) return 0;
  const style = box.style;
  const saved = PLACED.map((p) => style.getPropertyValue(p)) as [
    string,
    string,
    string,
    string,
  ];
  const height = root.offsetHeight;
  const width = box.offsetWidth;
  // Offsets are taken against the containing block (the positioned root):
  // leaving the flow can move it (a parent that centers it re-centers).
  const anchor = (box.offsetParent as HTMLElement | null) ?? root;
  const was = anchor.getBoundingClientRect();
  const rect = box.getBoundingClientRect();
  const scale = width > 0 && rect.width > 0 ? rect.width / width : 1;
  style.setProperty("position", "absolute");
  style.setProperty("top", "0px");
  style.setProperty("left", "0px");
  style.setProperty("width", `${width}px`);
  const is = anchor.getBoundingClientRect();
  const origin = box.getBoundingClientRect();
  const top = rect.top - was.top - (origin.top - is.top);
  const left = rect.left - was.left - (origin.left - is.left);
  style.setProperty("top", `${top / scale}px`);
  style.setProperty("left", `${left / scale}px`);
  const room = height - root.offsetHeight;
  LEFT.set(box, { room, style: saved });
  return room;
}

/** Put a reopening panel back in the flow. */
export function rejoinFlow(box: HTMLElement) {
  const left = LEFT.get(box);
  if (!left) return;
  LEFT.delete(box);
  PLACED.forEach((p, i) => {
    const value = left.style[i];
    if (value) box.style.setProperty(p, value);
    else box.style.removeProperty(p);
  });
}

/** The room an in-flow panel takes in `root`: what it adds to its height. */
export function flowRoom(box: HTMLElement, root: HTMLElement): number {
  const height = root.offsetHeight;
  const position = box.style.getPropertyValue("position");
  box.style.setProperty("position", "absolute");
  const without = root.offsetHeight;
  if (position) box.style.setProperty("position", position);
  else box.style.removeProperty("position");
  return height - without;
}

/**
 * What a reveal root glides when a parent moves it (a stage that centers it
 * shifts it by half its new height in one step): an Accordion its own box; a
 * Collapsible its parent, which holds the content after it.
 */
function gliderOf(root: Element): HTMLElement | null {
  const el =
    root.getAttribute("data-slot") === "collapsible"
      ? root.parentElement
      : (root as HTMLElement);
  const doc = root.ownerDocument;
  // Never the page itself: a moved <body> would carry fixed layers with it.
  if (!el || el === doc.body || el === doc.documentElement) return null;
  return el;
}

/**
 * The nearest reveal root around this one. Whatever moves it in a change, its
 * own machinery puts it back (its glider glides, or its parent's FLIP group
 * plays it back), carrying this one along.
 */
function outerRootOf(root: Element): HTMLElement | null {
  return (root.parentElement?.closest(ROOTS) as HTMLElement | null) ?? null;
}

/** Running glides by element. */
const GLIDES = new WeakMap<Element, Animation>();

interface Drawn {
  own: DOMRect;
  outer: DOMRect | null;
}

/**
 * Glide a root's glider from where it was drawn at the click back to rest, on
 * the panels' clock, so nothing above the panel jumps. Nested: the glider
 * moves by its own displacement minus the outer root's — the outer root is
 * put back (glided or FLIPped) and carries it that far — so a nested root
 * that just rides along doesn't move twice as far, and one its own stage
 * re-centers still glides.
 */
function glide(root: HTMLElement, before: Drawn, t: RevealTiming) {
  const el = gliderOf(root);
  if (!el) return;
  GLIDES.get(el)?.cancel();
  GLIDES.delete(el);
  if (t.reduce || typeof el.animate !== "function") return;
  const now = el.getBoundingClientRect();
  let dx = before.own.left - now.left;
  let dy = before.own.top - now.top;
  const outer = before.outer && outerRootOf(root)?.getBoundingClientRect();
  if (before.outer && outer) {
    dx -= before.outer.left - outer.left;
    dy -= before.outer.top - outer.top;
  }
  if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) return;
  const [x, y] = ownTranslate(el) ?? ["0px", "0px"];
  const animation = el.animate(
    [
      { translate: `${plus(x, dx)} ${plus(y, dy)}` },
      { translate: `${x} ${y}` },
    ],
    { duration: t.ms, easing: t.ease },
  );
  GLIDES.set(el, animation);
  animation.onfinish = () => {
    if (GLIDES.get(el) === animation) GLIDES.delete(el);
  };
}

export interface RevealOptions {
  /**
   * Re-measure and FLIP what the change moved, synchronously (it runs inside
   * `flushSync`, before the snapped layout is painted).
   */
  flip: (move: { ms: number; ease: string }) => void;
  /** Sweep the root's own panels among the changed toggles (true = opened). */
  sweep: (changed: Map<HTMLElement, boolean>, t: RevealTiming) => void;
}

/**
 * Watches every open state under a reveal root (nested Accordions and
 * Collapsibles too, so their height changes move this root's content as
 * well). On a change, in the same task as the click: closing Collapsible
 * panels leave the flow, `flip` runs, the root's glider glides if a parent
 * moved it, and `sweep` sweeps the root's own panels — all on one clock.
 */
export function useReveal(
  rootRef: React.RefObject<HTMLElement | null>,
  options: RevealOptions,
) {
  const latest = React.useRef(options);
  useIsoLayoutEffect(() => {
    latest.current = options;
  });
  React.useEffect(() => {
    const root = rootRef.current;
    const view = root?.ownerDocument.defaultView;
    if (!root || !view || typeof MutationObserver === "undefined") return;
    // Where the gliders are drawn just before a click toggles something
    // (capture runs before Radix's handler); a click that toggles nothing
    // forgets it. Programmatic changes have no baseline and don't glide.
    let before: Drawn | null = null;
    let forget: number | undefined;
    const remember = () => {
      const own = gliderOf(root);
      if (!own) return;
      before = {
        own: own.getBoundingClientRect(),
        outer: outerRootOf(root)?.getBoundingClientRect() ?? null,
      };
      view.clearTimeout(forget);
      forget = view.setTimeout(() => {
        before = null;
      });
    };
    root.addEventListener("click", remember, true);
    const observer = new MutationObserver((records) => {
      const changed = new Map<HTMLElement, boolean>();
      for (const record of records) {
        const el = record.target as HTMLElement;
        if (!TOGGLES.has(el.getAttribute("data-slot") ?? "")) continue;
        const state = el.getAttribute("data-state");
        if (state === record.oldValue) continue;
        changed.set(el, state === "open");
      }
      if (changed.size === 0) return;
      // Before anything measures: closing Collapsible panels leave the flow,
      // reopening ones come back (Accordion panels do it in CSS).
      for (const [el, open] of changed) {
        if (el.getAttribute("data-slot") !== "collapsible") continue;
        const box = contentOf(el);
        if (!box) continue;
        if (open) rejoinFlow(box);
        else leaveFlow(box, el);
      }
      const t = revealTiming(root, [...changed.values()].includes(true));
      flushSync(() => latest.current.flip({ ms: t.ms, ease: t.ease }));
      if (before) glide(root, before, t);
      before = null;
      latest.current.sweep(changed, t);
    });
    observer.observe(root, {
      subtree: true,
      attributes: true,
      attributeFilter: ["data-state"],
      attributeOldValue: true,
    });
    return () => {
      observer.disconnect();
      root.removeEventListener("click", remember, true);
      view.clearTimeout(forget);
    };
  }, [rootRef]);
}
